const pending=[];const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function req(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:auth,body:body?JSON.stringify(body):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function node(title,body,tools=''){return `<div class="tree-node"><div class="tree-line"><button class="tree-toggle">∨</button><span>${title}</span>${tools}</div><div class="tree-children">${body}</div></div>`}
function edit(b){const x=b.closest('.tree-node').querySelector(':scope > .tree-children > .tree-editor');x.hidden=!x.hidden}
async function render(){try{const d=await req('/api/admin/status'),f=d.file,paused=d.meta.feed_paused==='true';$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#app-version').textContent='Version '+d.version;$('#file-status').textContent=f.exists?`Reading ${f.configured} · ${f.bytes} bytes`:`Waiting for ${f.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#feed-toggle').textContent=paused?'Start live updates':'Stop live updates ('+d.pollSeconds+'s)';$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:paused});render()};let save=$('#save-setup');if(!save){save=document.createElement('button');save.id='save-setup';save.className='btn yellow';$('#feed-toggle').after(save)}save.textContent='Save setup'+(pending.length?' ('+pending.length+')':'');save.onclick=async()=>{if(pending.length)await req('/api/admin/assignments',{assignments:pending.splice(0)});await req('/api/admin/save',{});render()};const configured=d.tournaments.map(t=>t.name),unassigned=d.events.filter(e=>!configured.includes(e.tournament));let body='<div class="tree-editor" hidden><input id="new-tournament" placeholder="Tournament name"><button class="btn make-tournament">Create</button></div>';
body+=d.tournaments.map(t=>{const ls=d.levels.filter(l=>l.tournament_id===t.id);return node('<strong>'+esc(t.name)+'</strong>',ls.map(l=>{const rs=d.races.filter(r=>r.level_id===l.id);return node('<strong>'+esc(l.name)+'</strong>',rs.map(r=>{const es=d.events.filter(e=>e.tournament===t.name&&e.level===l.name&&e.stage===r.name);return node(esc(r.name),es.map(e=>`<div class="tree-leaf">${esc(e.name)} · Visibility: <button class="visibility" data-id="${esc(e.id)}">${e.visible?'True':'False'}</button></div>`).join('')+(es.length?'<div class="empty-tree">Awaiting next RaceTec export</div>':'<div class="empty-tree">No RaceTec race assigned</div>'),`<button class="lap-toggle" data-r="${r.id}">Fastest lap: ${r.fastest_lap?'On':'Off'}</button>`) }).join('')+`<div class="tree-editor" hidden><input placeholder="Heat / race name"><button class="btn make-race" data-t="${t.id}" data-l="${l.id}">Create</button></div>`,'<button class="tree-add editor-open">+</button>')}).join('')+`<div class="tree-editor" hidden><input placeholder="Level name, e.g. Qualifiers"><button class="btn make-level" data-t="${t.id}">Create</button></div>`,'<button class="tree-add editor-open">+</button>')}).join('');$('#event-list').innerHTML=`<div class="object-tree">${node('<strong>Tournaments</strong>',body,'<button class="tree-add editor-open">+</button>')}${node('<strong>Unassigned RaceTec races</strong>',unassigned.length?unassigned.map(e=>`<div class="tree-leaf unassigned-race"><span>${esc(e.name)}</span><select><option value="">Assign to a heat…</option>${d.races.map(r=>{const l=d.levels.find(x=>x.id===r.level_id),t=d.tournaments.find(x=>x.id===r.tournament_id);return l&&t?`<option value="${r.id}">${esc(t.name)} → ${esc(l.name)} → ${esc(r.name)}</option>`:''}).join('')}</select><button class="btn assign-from-bottom" data-e="${esc(e.id)}">Assign</button></div>`).join(''):'<div class="empty-tree">Everything is assigned.</div>')}</div>`;$('#event-list').prepend(Object.assign(document.createElement('button'),{className:'btn yellow',textContent:'Create Women, Open & Groms structure',onclick:async()=>{await req('/api/admin/standard-structure',{});render()}}));$('#event-list').querySelectorAll('.tree-toggle').forEach(b=>b.onclick=()=>{const c=b.closest('.tree-node').querySelector(':scope > .tree-children');c.hidden=!c.hidden;b.textContent=c.hidden?'›':'∨'});$('#event-list').querySelectorAll('.editor-open').forEach(b=>b.onclick=()=>edit(b));$('.make-tournament').onclick=async()=>{const n=$('#new-tournament').value.trim();if(n){await req('/api/admin/tournaments',{name:n});render()}};$('#event-list').querySelectorAll('.make-level').forEach(b=>b.onclick=async()=>{const n=b.parentElement.querySelector('input').value.trim();if(n){await req('/api/admin/levels',{tournamentId:+b.dataset.t,name:n});render()}});$('#event-list').querySelectorAll('.make-race').forEach(b=>b.onclick=async()=>{const n=b.parentElement.querySelector('input').value.trim();if(n){await req('/api/admin/races',{tournamentId:+b.dataset.t,levelId:+b.dataset.l,name:n});render()}});$('#event-list').querySelectorAll('.lap-toggle').forEach(b=>b.onclick=async()=>{const r=d.races.find(x=>x.id===+b.dataset.r);await req('/api/admin/races/'+r.id+'/fastest-lap',{enabled:!r.fastest_lap});render()});$('#event-list').querySelectorAll('.assign-from-bottom').forEach(b=>b.onclick=()=>{const r=d.races.find(x=>x.id===+b.parentElement.querySelector('select').value),e=d.events.find(x=>x.id===b.dataset.e);if(!r||!e)return;const l=d.levels.find(x=>x.id===r.level_id),t=d.tournaments.find(x=>x.id===r.tournament_id);pending.push({eventId:e.id,tournament:t.name,level:l.name,race:r.name,raceId:r.id,name:e.name});b.textContent='Pending save';b.disabled=true;save.textContent='Save setup ('+pending.length+')'});$('#event-list').querySelectorAll('.visibility').forEach(b=>b.onclick=async()=>{await req('/api/admin/events/'+encodeURIComponent(b.dataset.id),{visible:b.textContent!=='True'});render()})}catch(e){$('#event-list').textContent=e.message}}render();

